class Solution {
    long long countUpTo(long long n, int digit) {
        if (n <= 0) {
            return 0;
        }
        long long result = 0;
        for (long long place = 1; place <= n; place *= 10) {
            long long high = n / place / 10;
            long long current = (n / place) % 10;
            long long low = n % place;
            if (digit != 0) {
                result += high * place;
                if (current > digit) {
                    result += place;
                } else if (current == digit) {
                    result += low + 1;
                }
            } else if (high > 0) {
                result += (high - 1) * place;
                if (current > 0) {
                    result += place;
                } else {
                    result += low + 1;
                }
            }
            if (place > n / 10) {
                break;
            }
        }
        return result;
    }

public:
    int digitsCount(int d, int low, int high) {
        return static_cast<int>(countUpTo(high, d) - countUpTo(low - 1LL, d));
    }
};
